class switch_scoreboard extends uvm_scoreboard; `uvm_component_utils(switch_scoreboard) uvm_analysis_imp #(switch_item,switch_scoreboard) imp; int seen[4]; function new(string n,uvm_component p);super.new(n,p);imp=new("imp",this);endfunction function void write(switch_item t); seen[t.dst]++; `uvm_info("SCORE",$sformatf("dst=%0d data=%08x seen=%0d",t.dst,t.data,seen[t.dst]),UVM_HIGH) endfunction function void report_phase(uvm_phase p); foreach(seen[i]) `uvm_info("SUMMARY",$sformatf("port %0d packets=%0d",i,seen[i]),UVM_LOW) endfunction endclass
